def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my_last, opp_last = history[-1]
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'
    opp_c = 0
    my_def = 0
    opp_def = 0
    retaliation_detected = False
    for i, (m, o) in enumerate(history):
        if o == 'C':
            opp_c += 1
        else:
            opp_def += 1
        if m == 'D':
            my_def += 1
            if i + 1 < n and history[i+1][1] == 'D':
                retaliation_detected = True
    if opp_def == n:
        return 'D'
    if n >= 10 and opp_def * 2 > n:
        return 'D'
    if opp_c <= 2 and n >= 8:
        return 'D'
    if retaliation_detected:
        if opp_last == 'D':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            return 'C'
    if opp_last == 'D':
        if rng.random() < 0.2:
            return 'C'
        return 'D'
    if my_last == 'D':
        return 'C'
    if my_def * 4 < n:
        if opp_c >= n - 2:
            p = 0.25
        else:
            p = 0.1
        if rng.random() < p:
            return 'D'
    return 'C'
